  `chanceFirepot1` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `chanceFirepot2` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `chanceFirepot3` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `fireCount1` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `fireCount2` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `fireCount3` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `lines_percent_config_spin` text COLLATE utf8mb4_unicode_ci,
  `lines_percent_config_spin_bonus` text COLLATE utf8mb4_unicode_ci,
  `lines_percent_config_bonus` text COLLATE utf8mb4_unicode_ci,
  `lines_percent_config_bonus_bonus` text COLLATE utf8mb4_unicode_ci,
  `rezerv` varchar(55) COLLATE utf8mb4_unicode_ci DEFAULT '',
  `cask` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT '',
  `advanced` text COLLATE utf8mb4_unicode_ci,
  `bet` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `scaleMode` enum('','showAll','exactFit') COLLATE utf8mb4_unicode_ci NOT NULL,
  `slotViewState` enum('','Normal','HideUI') COLLATE utf8mb4_unicode_ci NOT NULL,
  `view` int NOT NULL DEFAULT '0',
  `denomination` decimal(20,2) NOT NULL DEFAULT '1.00',
  `category_temp` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `original_id` int NOT NULL DEFAULT '0',
  `bids` int NOT NULL DEFAULT '0',
  `stat_in` decimal(20,4) NOT NULL DEFAULT '0.0000',
  `stat_out` decimal(20,4) NOT NULL DEFAULT '0.0000',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `current_rtp` decimal(20,4) NOT NULL DEFAULT '0.0000',
  `rtp_stat_in` decimal(20,4) NOT NULL DEFAULT '0.0000',
  `rtp_stat_out` decimal(20,4) NOT NULL DEFAULT '0.0000',
  PRIMARY KEY (`id`),
  KEY `name` (`name`),
  KEY `shop_id` (`shop_id`),
  KEY `device` (`device`),
  KEY `view` (`view`),
  KEY `original_id` (`original_id`),
  KEY `bids` (`bids`),
  KEY `stat_in` (`stat_in`),
  KEY `stat_out` (`stat_out`)
) ENGINE=InnoDB AUTO_INCREMENT=6647 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

DROP TABLE IF EXISTS `w_happyhours`;
CREATE TABLE `w_happyhours` (
  `id` int NOT NULL AUTO_INCREMENT,
  `multiplier` varchar(55) COLLATE utf8mb4_unicode_ci NOT NULL,
  `wager` int NOT NULL,
  `time` varchar(55) COLLATE utf8mb4_unicode_ci NOT NULL,
  `shop_id` int NOT NULL,
  `status` int NOT NULL DEFAULT '1',
  PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;


DROP TABLE IF EXISTS `w_info`;
CREATE TABLE `w_info` (
  `id` int NOT NULL AUTO_INCREMENT,
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `text` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `roles` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `user_id` int NOT NULL,
  `days` int NOT NULL DEFAULT '3',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

DROP TABLE IF EXISTS `w_info_shop`;
CREATE TABLE `w_info_shop` (
  `id` int NOT NULL AUTO_INCREMENT,
  `info_id` int NOT NULL,
  `shop_id` int NOT NULL,
  PRIMARY KEY (`id`),
  KEY `category_id` (`shop_id`),
  KEY `game_id` (`info_id`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

DROP TABLE IF EXISTS `w_invites`;
CREATE TABLE `w_invites` (
  `id` int NOT NULL AUTO_INCREMENT,
  `type` varchar(55) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `message` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `sum` double NOT NULL DEFAULT '0',
  `sum_ref` double NOT NULL DEFAULT '0',
  `min_amount` double NOT NULL DEFAULT '0',
  `waiting_time` int NOT NULL,
  `shop_id` int NOT NULL,
  `wager` int NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

DROP TABLE IF EXISTS `w_jobs`;
CREATE TABLE `w_jobs` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `queue` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `payload` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `attempts` tinyint unsigned NOT NULL,
  `reserved_at` int unsigned DEFAULT NULL,
  `available_at` int unsigned NOT NULL,
  `created_at` int unsigned NOT NULL,
  PRIMARY KEY (`id`),
  KEY `jobs_queue_index` (`queue`)
) ENGINE=MyISAM AUTO_INCREMENT=331 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

DROP TABLE IF EXISTS `w_jpg`;
CREATE TABLE `w_jpg` (
  `id` int NOT NULL AUTO_INCREMENT,
  `date_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `balance` decimal(20,6) NOT NULL DEFAULT '0.000000',
  `start_balance` int NOT NULL DEFAULT '1',
  `pay_sum` int NOT NULL,
  `percent` decimal(5,2) NOT NULL,
  `user_id` int DEFAULT NULL,
  `shop_id` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `shop_id` (`shop_id`)
) ENGINE=InnoDB AUTO_INCREMENT=61 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

DROP TABLE IF EXISTS `w_lotto_draws`;
CREATE TABLE `w_lotto_draws` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `lotto_game_id` bigint unsigned NOT NULL,
  `round_code` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `winning_numbers_json` json NOT NULL,
  `jackpot_paid` decimal(15,2) DEFAULT '0.00',
  `draw_date` date NOT NULL,
  `scheduled_for` timestamp NULL DEFAULT NULL,
  `status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'scheduled',
  `draw_source` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'local',
  `total_tickets` int NOT NULL DEFAULT '0',
  `total_winners` int NOT NULL DEFAULT '0',
  `total_paid` decimal(14,2) NOT NULL DEFAULT '0.00',
  `drawn_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `lotto_draws_game_round_unique` (`lotto_game_id`,`round_code`),
  KEY `w_lotto_draws_lotto_game_id_index` (`lotto_game_id`)
) ENGINE=InnoDB AUTO_INCREMENT=22 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `w_lotto_games`;
CREATE TABLE `w_lotto_games` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `title` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `slug` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `pick_count` int NOT NULL DEFAULT '4',
  `max_number` int NOT NULL DEFAULT '20',
  `entry_fee` decimal(14,2) NOT NULL DEFAULT '500.00',
  `jackpot_pool` decimal(14,2) NOT NULL DEFAULT '100000.00',
  `draw_interval` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'daily',
  `draw_time` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '23:55',
  `draw_source` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'local',
  `result_columns_json` json DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `w_lotto_games_slug_unique` (`slug`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `w_lotto_tickets`;
CREATE TABLE `w_lotto_tickets` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `lotto_game_id` bigint unsigned NOT NULL,
  `lotto_draw_id` bigint unsigned DEFAULT NULL,
  `user_id` bigint unsigned NOT NULL,
  `numbers_json` json NOT NULL,
  `draw_date` date NOT NULL,
  `status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `prize_won` decimal(15,2) DEFAULT '0.00',
  `matches_count` int NOT NULL DEFAULT '0',
  `payout_amount` decimal(14,2) NOT NULL DEFAULT '0.00',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `w_lotto_tickets_lotto_game_id_index` (`lotto_game_id`),
  KEY `w_lotto_tickets_user_id_index` (`user_id`),
  KEY `w_lotto_tickets_lotto_draw_id_index` (`lotto_draw_id`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `w_manual_deposits`;
CREATE TABLE `w_manual_deposits` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint unsigned NOT NULL,
  `payment_intent_id` bigint unsigned NOT NULL,
  `account_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `transaction_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `screenshot` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `admin_note` text COLLATE utf8mb4_unicode_ci,
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '0: Pending, 1: Approved, 2: Rejected',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `w_manual_deposits_user_id_index` (`user_id`),
  KEY `w_manual_deposits_payment_intent_id_index` (`payment_intent_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `w_messages`;
CREATE TABLE `w_messages` (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` int NOT NULL,
  `type` varchar(55) COLLATE utf8mb4_unicode_ci NOT NULL,
  `value` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` int NOT NULL DEFAULT '0',
  `shop_id` int NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=59 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `w_migrations`;
CREATE TABLE `w_migrations` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `migration` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `batch` int NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=35 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `w_notifications`;
CREATE TABLE `w_notifications` (
  `id` int NOT NULL AUTO_INCREMENT,
  `notification` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
