  `user_id` int NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `w_open_shift`;
CREATE TABLE `w_open_shift` (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` int NOT NULL,
  `balance` decimal(20,4) NOT NULL DEFAULT '0.0000',
  `balance_in` decimal(20,4) NOT NULL DEFAULT '0.0000',
  `balance_out` decimal(20,4) NOT NULL DEFAULT '0.0000',
  `users` decimal(20,4) NOT NULL DEFAULT '0.0000',
  `jpg` decimal(20,4) NOT NULL DEFAULT '0.0000',
  `money_in` decimal(20,4) NOT NULL DEFAULT '0.0000',
  `money_out` decimal(20,4) NOT NULL DEFAULT '0.0000',
  `transfers` int NOT NULL DEFAULT '0',
  `old_banks` decimal(20,4) NOT NULL DEFAULT '0.0000',
  `old_total` decimal(20,4) NOT NULL DEFAULT '0.0000',
  `last_banks` decimal(20,4) NOT NULL DEFAULT '0.0000',
  `shop_id` int NOT NULL,
  `start_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `end_date` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `shop_id` (`shop_id`),
  KEY `user_id` (`user_id`)
) ENGINE=MyISAM AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

DROP TABLE IF EXISTS `w_open_shift_temp`;
