  KEY `w_payment_intents_user_id_index` (`user_id`),
  KEY `w_payment_intents_driver_index` (`driver`),
  KEY `w_payment_intents_status_index` (`status`),
  KEY `w_payment_intents_external_id_index` (`external_id`)
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `w_payment_settings`;
CREATE TABLE `w_payment_settings` (
  `id` int NOT NULL AUTO_INCREMENT,
  `system` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `field` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `shop_id` int NOT NULL,
  `value` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=29 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `w_payments`;
CREATE TABLE `w_payments` (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` int NOT NULL,
  `sum` float NOT NULL,
