  `credit_id` int NOT NULL DEFAULT '0',
  `status` int NOT NULL,
  `shop_id` int NOT NULL,
  PRIMARY KEY (`id`),
  KEY `user_id` (`user_id`)
) ENGINE=MyISAM AUTO_INCREMENT=93 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

DROP TABLE IF EXISTS `w_permission_role`;
CREATE TABLE `w_permission_role` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `permission_id` int unsigned NOT NULL,
  `role_id` int unsigned NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `permission_role_permission_id_index` (`permission_id`),
  KEY `permission_role_role_id_index` (`role_id`)
) ENGINE=MyISAM AUTO_INCREMENT=956 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;


DROP TABLE IF EXISTS `w_permission_user`;
CREATE TABLE `w_permission_user` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `permission_id` int unsigned NOT NULL,
  `user_id` int unsigned NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `permission_user_permission_id_index` (`permission_id`),
  KEY `permission_user_user_id_index` (`user_id`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

DROP TABLE IF EXISTS `w_permissions`;
CREATE TABLE `w_permissions` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `slug` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `model` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `group_id` int NOT NULL DEFAULT '0',
  `rank` int NOT NULL DEFAULT '0',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `permissions_slug_unique` (`slug`)
) ENGINE=MyISAM AUTO_INCREMENT=140 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;


DROP TABLE IF EXISTS `w_personal_access_tokens`;
CREATE TABLE `w_personal_access_tokens` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `tokenable_type` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `tokenable_id` bigint unsigned NOT NULL,
  `name` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `token` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `abilities` text COLLATE utf8mb4_unicode_ci,
  `last_used_at` timestamp NULL DEFAULT NULL,
  `expires_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `w_personal_access_tokens_token_unique` (`token`),
  KEY `w_personal_access_tokens_tokenable_type_tokenable_id_index` (`tokenable_type`,`tokenable_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `w_pincodes`;
CREATE TABLE `w_pincodes` (
  `id` int NOT NULL AUTO_INCREMENT,
  `code` varchar(55) COLLATE utf8mb4_unicode_ci NOT NULL,
  `nominal` int NOT NULL,
  `user_id` int DEFAULT NULL,
  `status` int NOT NULL DEFAULT '1',
  `shop_id` int DEFAULT NULL,
  `activated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `user_id` (`user_id`),
  KEY `shop_id` (`shop_id`)
) ENGINE=MyISAM AUTO_INCREMENT=13 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

DROP TABLE IF EXISTS `w_prediction_markets`;
CREATE TABLE `w_prediction_markets` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `market_id` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `creator_id` bigint unsigned DEFAULT NULL,
  `category` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'custom',
  `title` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text COLLATE utf8mb4_unicode_ci,
  `verification_url` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `pool_yes` decimal(14,2) NOT NULL DEFAULT '1000.00',
  `pool_no` decimal(14,2) NOT NULL DEFAULT '1000.00',
  `end_date` timestamp NOT NULL,
  `status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'active',
  `resolution` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `w_prediction_markets_market_id_unique` (`market_id`),
  KEY `w_prediction_markets_creator_id_index` (`creator_id`),
  KEY `w_prediction_markets_category_index` (`category`),
  KEY `w_prediction_markets_end_date_index` (`end_date`),
  KEY `w_prediction_markets_status_index` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `w_prediction_votes`;
CREATE TABLE `w_prediction_votes` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint unsigned NOT NULL,
  `market_id` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `choice` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL,
  `odds` decimal(8,2) NOT NULL DEFAULT '2.00',
  `share_price` decimal(6,2) NOT NULL DEFAULT '0.50',
  `shares_count` decimal(14,2) NOT NULL DEFAULT '0.00',
  `stake` decimal(14,2) NOT NULL,
  `potential_win` decimal(14,2) NOT NULL,
  `status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `payout_amount` decimal(14,2) NOT NULL DEFAULT '0.00',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `w_prediction_votes_user_id_index` (`user_id`),
  KEY `w_prediction_votes_market_id_index` (`market_id`),
  KEY `w_prediction_votes_status_index` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=15 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `w_progress`;
CREATE TABLE `w_progress` (
  `id` int NOT NULL AUTO_INCREMENT,
  `sum` double NOT NULL DEFAULT '0',
  `type` enum('one_pay','sum_pay') COLLATE utf8mb4_unicode_ci NOT NULL,
  `spins` int NOT NULL DEFAULT '0',
  `bet` double NOT NULL,
  `rating` int NOT NULL,
  `bonus` double NOT NULL DEFAULT '0',
  `day` varchar(55) COLLATE utf8mb4_unicode_ci NOT NULL,
  `min` int NOT NULL,
  `max` int NOT NULL,
  `percent` float NOT NULL,
  `min_balance` double NOT NULL,
  `wager` int NOT NULL,
  `days_active` int NOT NULL DEFAULT '5',
  `status` int NOT NULL DEFAULT '1',
  `shop_id` int NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=201 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;


DROP TABLE IF EXISTS `w_progress_users`;
CREATE TABLE `w_progress_users` (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` int NOT NULL,
  `rating` int NOT NULL,
  `sum` double NOT NULL DEFAULT '0',
  `spins` int NOT NULL DEFAULT '0',
  `progress_id` int NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=58 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

DROP TABLE IF EXISTS `w_rewards`;
CREATE TABLE `w_rewards` (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` int NOT NULL,
  `referral_id` int NOT NULL,
  `payed` decimal(10,0) NOT NULL DEFAULT '0',
  `sum` decimal(20,4) NOT NULL,
  `ref_sum` decimal(20,4) NOT NULL,
  `activated` int NOT NULL DEFAULT '0',
  `user_received` int NOT NULL DEFAULT '0',
  `referral_received` int NOT NULL DEFAULT '0',
  `until` timestamp NULL DEFAULT NULL,
  `shop_id` int NOT NULL DEFAULT '0',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `user_id` (`user_id`),
  KEY `referral_id` (`referral_id`),
  KEY `activated` (`activated`),
  KEY `user_received` (`user_received`),
  KEY `referral_received` (`referral_received`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `w_role_user`;
CREATE TABLE `w_role_user` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `role_id` int unsigned NOT NULL,
  `user_id` int unsigned NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `role_user_role_id_index` (`role_id`),
  KEY `role_user_user_id_index` (`user_id`)
) ENGINE=MyISAM AUTO_INCREMENT=198 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;


DROP TABLE IF EXISTS `w_roles`;
CREATE TABLE `w_roles` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `slug` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `level` int NOT NULL DEFAULT '1',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `roles_slug_unique` (`slug`)
) ENGINE=MyISAM AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;


DROP TABLE IF EXISTS `w_rules`;
CREATE TABLE `w_rules` (
  `id` int NOT NULL AUTO_INCREMENT,
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `href` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `keywords` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `description` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `text` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;


DROP TABLE IF EXISTS `w_securities`;
CREATE TABLE `w_securities` (
  `id` int NOT NULL AUTO_INCREMENT,
  `type` enum('game','user_balance','user_in_out','user_balance_bigger','shop','shop_balance_bigger','user_win') COLLATE utf8mb4_unicode_ci NOT NULL,
  `bank` varchar(55) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `item_id` int NOT NULL,
  `pay_in` double DEFAULT NULL,
  `pay_out` double DEFAULT NULL,
  `pay_total` double DEFAULT NULL,
  `balance` double DEFAULT NULL,
  `win` double DEFAULT NULL,
  `rtp` double DEFAULT NULL,
  `count` int DEFAULT NULL,
  `view` int NOT NULL DEFAULT '1',
  `sms` int NOT NULL DEFAULT '0',
  `block` int NOT NULL DEFAULT '0',
  `category` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `shop_id` int NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `item_id` (`item_id`),
  KEY `type` (`type`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `w_sessions`;
CREATE TABLE `w_sessions` (
  `id` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `user_id` int DEFAULT NULL,
  `ip_address` varchar(45) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `user_agent` text COLLATE utf8mb4_unicode_ci,
  `payload` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `last_activity` int NOT NULL,
  `country` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `city` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `os` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `device` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `browser` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

DROP TABLE IF EXISTS `w_settings`;
CREATE TABLE `w_settings` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `key` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `value` text COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`id`),
  KEY `settings_key_index` (`key`)
) ENGINE=MyISAM AUTO_INCREMENT=91 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;


DROP TABLE IF EXISTS `w_shops`;
CREATE TABLE `w_shops` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `balance` decimal(20,4) NOT NULL DEFAULT '0.0000',
  `frontend` varchar(55) COLLATE utf8mb4_unicode_ci NOT NULL,
  `currency` varchar(5) COLLATE utf8mb4_unicode_ci DEFAULT '',
  `percent` int NOT NULL DEFAULT '90',
  `max_win` int NOT NULL DEFAULT '100',
  `shop_limit` int NOT NULL DEFAULT '200',
  `is_blocked` int NOT NULL DEFAULT '0',
  `access` int DEFAULT '0',
  `country` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `os` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `device` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `orderby` enum('AZ','Rand','RTP','Count','Date') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'AZ',
  `user_id` int NOT NULL,
  `pending` int NOT NULL DEFAULT '0',
  `rules_terms_and_conditions` int NOT NULL DEFAULT '0',
  `rules_privacy_policy` int NOT NULL DEFAULT '0',
  `rules_general_bonus_policy` int NOT NULL DEFAULT '0',
  `rules_why_bitcoin` int NOT NULL DEFAULT '0',
  `rules_responsible_gaming` int NOT NULL DEFAULT '0',
  `happyhours_active` int NOT NULL DEFAULT '1',
  `progress_active` int NOT NULL DEFAULT '1',
  `invite_active` int NOT NULL DEFAULT '1',
  `welcome_bonuses_active` int NOT NULL DEFAULT '1',
  `sms_bonuses_active` int NOT NULL DEFAULT '1',
  `wheelfortune_active` int DEFAULT '1',
  PRIMARY KEY (`id`),
  KEY `name` (`name`(191))
) ENGINE=MyISAM AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;


DROP TABLE IF EXISTS `w_shops_user`;
CREATE TABLE `w_shops_user` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `shop_id` int NOT NULL,
  `user_id` int NOT NULL,
  PRIMARY KEY (`id`),
  KEY `w_shops_user_shop_id_index` (`shop_id`),
  KEY `w_shops_user_user_id_index` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=24 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `w_sms`;
CREATE TABLE `w_sms` (
  `id` int NOT NULL AUTO_INCREMENT,
  `type` enum('invite','verification') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'invite',
  `message` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `message_id` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `user_id` int NOT NULL,
  `new_user_id` int DEFAULT NULL,
  `shop_id` int NOT NULL,
  `status` varchar(55) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `payed` int NOT NULL DEFAULT '0',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

DROP TABLE IF EXISTS `w_sms_bonus_items`;
CREATE TABLE `w_sms_bonus_items` (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` int NOT NULL,
  `days` int NOT NULL,
  `sms_bonus_id` int NOT NULL,
  `bonus` decimal(20,4) NOT NULL,
  `status` int NOT NULL DEFAULT '0',
  `shop_id` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `w_sms_bonuses`;
CREATE TABLE `w_sms_bonuses` (
  `id` int NOT NULL AUTO_INCREMENT,
  `days` int NOT NULL,
  `bonus` double NOT NULL,
  `wager` int NOT NULL,
  `shop_id` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=57 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `w_sms_mailing_messages`;
CREATE TABLE `w_sms_mailing_messages` (
  `id` int NOT NULL AUTO_INCREMENT,
  `sms_mailing_id` int NOT NULL,
  `user_id` int NOT NULL,
  `sent` int NOT NULL DEFAULT '0',
  `shop_id` int NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `w_sms_mailings`;
CREATE TABLE `w_sms_mailings` (
  `id` int NOT NULL AUTO_INCREMENT,
  `theme` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `message` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `roles` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `statuses` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `date_start` datetime DEFAULT NULL,
  `priority` int NOT NULL DEFAULT '0',
  `status` enum('active','waiting','completed') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'active',
  `shop_id` int NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `w_sports_bet_items`;
CREATE TABLE `w_sports_bet_items` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `bet_id` bigint unsigned NOT NULL,
  `market_id` bigint unsigned NOT NULL,
  `outcome_id` bigint unsigned NOT NULL,
  `odds` decimal(28,8) NOT NULL DEFAULT '0.00000000',
  `status` tinyint NOT NULL DEFAULT '2' COMMENT '1: Win, 2: Pending, 3: Loss, 4: Refunded',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `w_sports_bet_items_bet_id_index` (`bet_id`),
  KEY `w_sports_bet_items_market_id_index` (`market_id`),
  KEY `w_sports_bet_items_outcome_id_index` (`outcome_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `w_sports_bets`;
CREATE TABLE `w_sports_bets` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `bet_number` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `user_id` bigint unsigned NOT NULL,
  `type` tinyint NOT NULL DEFAULT '1' COMMENT '1: Single, 2: Multi',
  `legs_json` json DEFAULT NULL,
  `total_odds` decimal(10,2) NOT NULL DEFAULT '1.00',
  `stake` decimal(14,2) NOT NULL DEFAULT '0.00',
  `potential_win` decimal(14,2) NOT NULL DEFAULT '0.00',
  `stake_amount` decimal(28,8) NOT NULL DEFAULT '0.00000000',
  `return_amount` decimal(28,8) NOT NULL DEFAULT '0.00000000',
  `status` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT 'pending',
  `payout_amount` decimal(14,2) NOT NULL DEFAULT '0.00',
  `is_settled` tinyint NOT NULL DEFAULT '0',
  `result_time` datetime DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `w_sports_bets_bet_number_index` (`bet_number`),
  KEY `w_sports_bets_user_id_index` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `w_sports_categories`;
CREATE TABLE `w_sports_categories` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL,
  `odds_api_name` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `slug` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `icon` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `regions` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` tinyint NOT NULL DEFAULT '1',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `w_sports_categories_slug_unique` (`slug`),
  KEY `w_sports_categories_odds_api_name_index` (`odds_api_name`)
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `w_sports_cron_logs`;
CREATE TABLE `w_sports_cron_logs` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `job_alias` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `start_at` datetime DEFAULT NULL,
  `end_at` datetime DEFAULT NULL,
  `duration` int NOT NULL DEFAULT '0',
  `error` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `w_sports_cron_logs_job_alias_index` (`job_alias`)
) ENGINE=InnoDB AUTO_INCREMENT=50 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `w_sports_game_team`;
CREATE TABLE `w_sports_game_team` (
  `game_id` bigint unsigned NOT NULL,
  `team_id` bigint unsigned NOT NULL,
  PRIMARY KEY (`game_id`,`team_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `w_sports_games`;
CREATE TABLE `w_sports_games` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `ods_api_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `title` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `team_one_id` bigint unsigned NOT NULL DEFAULT '0',
  `team_two_id` bigint unsigned NOT NULL DEFAULT '0',
  `league_id` bigint unsigned NOT NULL,
  `slug` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `start_time` datetime NOT NULL,
  `bet_start_time` datetime DEFAULT NULL,
  `status` tinyint NOT NULL DEFAULT '1',
  `manually_added` tinyint NOT NULL DEFAULT '1',
  `is_outright` tinyint NOT NULL DEFAULT '0',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `w_sports_games_ods_api_id_index` (`ods_api_id`),
  KEY `w_sports_games_team_one_id_index` (`team_one_id`),
  KEY `w_sports_games_team_two_id_index` (`team_two_id`),
  KEY `w_sports_games_league_id_index` (`league_id`)
) ENGINE=InnoDB AUTO_INCREMENT=227 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `w_sports_leagues`;
CREATE TABLE `w_sports_leagues` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `odds_api_sport_key` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `category_id` bigint unsigned NOT NULL,
  `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `short_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `slug` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `has_outrights` tinyint NOT NULL DEFAULT '0',
  `image` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` tinyint NOT NULL DEFAULT '1',
  `api_status` tinyint NOT NULL DEFAULT '0',
  `manually_added` tinyint NOT NULL DEFAULT '1',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `w_sports_leagues_slug_unique` (`slug`),
  KEY `w_sports_leagues_odds_api_sport_key_index` (`odds_api_sport_key`),
  KEY `w_sports_leagues_category_id_index` (`category_id`)
) ENGINE=InnoDB AUTO_INCREMENT=176 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `w_sports_markets`;
CREATE TABLE `w_sports_markets` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `game_id` bigint unsigned NOT NULL,
  `market_type` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `outcome_type` tinyint NOT NULL DEFAULT '1',
  `player_props` tinyint NOT NULL DEFAULT '0',
  `game_period_market` tinyint NOT NULL DEFAULT '0',
  `title` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` tinyint NOT NULL DEFAULT '1',
  `locked` tinyint NOT NULL DEFAULT '0',
  `result_declared` tinyint NOT NULL DEFAULT '0',
  `win_outcome_id` bigint unsigned NOT NULL DEFAULT '0',
  `market_updated_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `w_sports_markets_game_id_index` (`game_id`),
  KEY `w_sports_markets_market_type_index` (`market_type`)
) ENGINE=InnoDB AUTO_INCREMENT=224 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `w_sports_matches`;
CREATE TABLE `w_sports_matches` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `sport_key` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `sport_title` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `match_id` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `home_team` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `away_team` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `start_time` timestamp NOT NULL,
  `odds_home` decimal(8,2) NOT NULL DEFAULT '1.90',
  `odds_draw` decimal(8,2) DEFAULT '3.20',
  `odds_away` decimal(8,2) NOT NULL DEFAULT '1.90',
  `status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'upcoming',
  `winner` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `home_score` int DEFAULT NULL,
  `away_score` int DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `w_sports_matches_match_id_unique` (`match_id`),
  KEY `w_sports_matches_sport_key_index` (`sport_key`),
  KEY `w_sports_matches_start_time_index` (`start_time`),
  KEY `w_sports_matches_status_index` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=478 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `w_sports_outcomes`;
CREATE TABLE `w_sports_outcomes` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `market_id` bigint unsigned NOT NULL,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `odds` decimal(28,8) NOT NULL,
  `point` decimal(5,2) DEFAULT NULL,
  `status` tinyint NOT NULL DEFAULT '1',
  `locked` tinyint NOT NULL DEFAULT '0',
  `winner` tinyint NOT NULL DEFAULT '0',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `w_sports_outcomes_market_id_index` (`market_id`)
) ENGINE=InnoDB AUTO_INCREMENT=522 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `w_sports_teams`;
CREATE TABLE `w_sports_teams` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `category_id` bigint unsigned NOT NULL DEFAULT '0',
  `slug` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `short_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `image` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `manually_added` tinyint NOT NULL DEFAULT '1',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `w_sports_teams_category_id_index` (`category_id`),
  KEY `w_sports_teams_name_index` (`name`)
) ENGINE=InnoDB AUTO_INCREMENT=417 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `w_stat_game`;
CREATE TABLE `w_stat_game` (
  `id` int NOT NULL AUTO_INCREMENT,
  `date_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `user_id` int NOT NULL,
  `balance` decimal(16,2) NOT NULL DEFAULT '0.00',
  `bet` decimal(20,4) NOT NULL DEFAULT '0.0000',
  `win` decimal(20,4) NOT NULL DEFAULT '0.0000',
  `game` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `in_game` decimal(20,4) NOT NULL DEFAULT '0.0000',
  `in_jpg` decimal(20,4) NOT NULL DEFAULT '0.0000',
  `in_profit` decimal(20,4) NOT NULL DEFAULT '0.0000',
  `denomination` decimal(20,4) NOT NULL DEFAULT '0.0000',
  `slots_bank` decimal(20,4) DEFAULT '0.0000',
  `bonus_bank` decimal(20,4) DEFAULT '0.0000',
  `fish_bank` decimal(20,4) DEFAULT '0.0000',
  `table_bank` decimal(20,4) DEFAULT '0.0000',
  `little_bank` decimal(20,4) DEFAULT '0.0000',
  `total_bank` decimal(20,4) DEFAULT '0.0000',
  `shop_id` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `user_id` (`user_id`) USING BTREE,
  KEY `game_id` (`game`) USING BTREE,
  KEY `date_time` (`date_time`) USING BTREE,
  KEY `shop_id` (`shop_id`),
  KEY `bet` (`bet`),
  KEY `balance` (`balance`),
  KEY `win` (`win`),
  KEY `in_profit` (`in_profit`)
) ENGINE=InnoDB AUTO_INCREMENT=21761 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

DROP TABLE IF EXISTS `w_statistics`;
CREATE TABLE `w_statistics` (
  `id` int NOT NULL AUTO_INCREMENT,
  `title` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `user_id` int NOT NULL,
  `payeer_id` int DEFAULT NULL,
  `system` enum('user','shop','bank','jpg','refund','happyhour','pincode','handpay','interkassa','coinbase','btcpayserver','invite','progress','tournament','daily_entry','welcome_bonus','sms_bonus','wheelfortune') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `old` decimal(20,4) NOT NULL,
  `sum` decimal(20,4) NOT NULL,
  `sum2` decimal(20,4) DEFAULT NULL,
  `hh_multiplier` int NOT NULL DEFAULT '1',
  `type` enum('add','out') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'add',
  `item_id` varchar(55) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` int NOT NULL DEFAULT '1',
  `ip_address` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `user_agent` varchar(550) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `country` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `city` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `os` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `device` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `browser` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `shop_id` int NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  PRIMARY KEY (`id`),
  KEY `system` (`system`),
  KEY `shop_id` (`shop_id`)
) ENGINE=MyISAM AUTO_INCREMENT=518 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

DROP TABLE IF EXISTS `w_statistics_add`;
