DROP TABLE IF EXISTS `w_stock_assets`;
CREATE TABLE `w_stock_assets` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `provider_id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `symbol` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `exchange` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `price_usd` decimal(18,6) DEFAULT NULL,
