  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `w_stock_assets_provider_id_unique` (`provider_id`),
  UNIQUE KEY `w_stock_assets_symbol_unique` (`symbol`),
  KEY `w_stock_assets_is_enabled_index` (`is_enabled`)
) ENGINE=InnoDB AUTO_INCREMENT=51 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `w_stock_positions`;
CREATE TABLE `w_stock_positions` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `user_id` int unsigned NOT NULL,
  `stock_asset_id` bigint unsigned NOT NULL,
  `stock_round_id` bigint unsigned NOT NULL,
  `requested_interval` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL,
  `direction` varchar(8) COLLATE utf8mb4_unicode_ci NOT NULL,
