  `stake` decimal(18,2) NOT NULL,
  `entry_price_usd` decimal(18,6) DEFAULT NULL,
  `exit_price_usd` decimal(18,6) DEFAULT NULL,
  `return_percent` decimal(12,6) DEFAULT NULL,
  `payout_amount` decimal(18,2) NOT NULL DEFAULT '0.00',
  `status` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'queued',
  `settled_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `w_stock_positions_stock_asset_id_foreign` (`stock_asset_id`),
  KEY `w_stock_positions_stock_round_id_foreign` (`stock_round_id`),
  KEY `w_stock_positions_user_id_created_at_index` (`user_id`,`created_at`),
  KEY `w_stock_positions_status_index` (`status`),
  CONSTRAINT `w_stock_positions_stock_asset_id_foreign` FOREIGN KEY (`stock_asset_id`) REFERENCES `w_stock_assets` (`id`) ON DELETE CASCADE,
  CONSTRAINT `w_stock_positions_stock_round_id_foreign` FOREIGN KEY (`stock_round_id`) REFERENCES `w_stock_rounds` (`id`) ON DELETE CASCADE,
  CONSTRAINT `w_stock_positions_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `w_users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `w_stock_price_snapshots`;
CREATE TABLE `w_stock_price_snapshots` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `stock_round_id` bigint unsigned NOT NULL,
  `stock_asset_id` bigint unsigned NOT NULL,
  `checkpoint` varchar(8) COLLATE utf8mb4_unicode_ci NOT NULL,
  `price_usd` decimal(18,6) NOT NULL,
  `observed_at` timestamp NOT NULL,
  `provider_updated_at` timestamp NULL DEFAULT NULL,
  `payload_hash` char(64) COLLATE utf8mb4_unicode_ci NOT NULL,
