  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `w_stock_price_snapshots_stock_round_id_checkpoint_unique` (`stock_round_id`,`checkpoint`),
  KEY `w_stock_price_snapshots_stock_asset_id_foreign` (`stock_asset_id`),
  CONSTRAINT `w_stock_price_snapshots_stock_asset_id_foreign` FOREIGN KEY (`stock_asset_id`) REFERENCES `w_stock_assets` (`id`) ON DELETE CASCADE,
  CONSTRAINT `w_stock_price_snapshots_stock_round_id_foreign` FOREIGN KEY (`stock_round_id`) REFERENCES `w_stock_rounds` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `w_stock_rounds`;
CREATE TABLE `w_stock_rounds` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `stock_asset_id` bigint unsigned NOT NULL,
  `interval` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL,
