  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `stock_round_asset_interval_start_unique` (`stock_asset_id`,`interval`,`starts_at`),
  UNIQUE KEY `w_stock_rounds_round_code_unique` (`round_code`),
  KEY `w_stock_rounds_starts_at_index` (`starts_at`),
  KEY `w_stock_rounds_ends_at_index` (`ends_at`),
  KEY `w_stock_rounds_status_index` (`status`),
  CONSTRAINT `w_stock_rounds_stock_asset_id_foreign` FOREIGN KEY (`stock_asset_id`) REFERENCES `w_stock_assets` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `w_subsessions`;
